fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // First, each pile must have at least m cookies to serve the special guests
    if a < m || b < m {
        return false;
    }

    // Compute the total cookies available and the total cookies required.
    // We cast to u16 to avoid overflow when adding two u8 values.
    let total_available = a as u16 + b as u16;
    // Regular guests need n cookies, special guests need 2*m cookies.
    let total_required = n as u16 + 2 * (m as u16);

    total_available >= total_required
}

